content:
{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello कोटेश्वर जी आपकी iron rack manufacturer की request IndiaMART पर raise है।"
    },
    {
      "i": 1,
      "speaker": "bot",
      "text": "बस उसी के लिए कुछ details confirm करनी थी।"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "Iron."
    },
    {
      "i": 3,
      "speaker": "caller",
      "text": "अभी का rack का height है।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "ठीक है मैं note कर लेता हूं।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "वैसे भाई आपको कितनी piece चाहिए होगी?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "कर लेता हूं।"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "अभी का rate कितना पैसा एक piece का?"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "देखिए price की जानकारी मेरे पास नहीं है लेकिन seller आपको best rates देंगे।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "बस आप अपनी quantity बता दीजिए ताकि मैं आपको सही seller से connect कर सकूं।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "आपको कितने piece चाहिए?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "पांच piece।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "ठीक है, 5 piece note कर लिए हैं।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "चलिए अब lot capacity के बारे में बात कर लेते हैं।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए?"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "500 kg का shelf या कुछ और?"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "सेलर से क्या चाहिए?"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "मेरा मतलब है कि एक shelf पर कितना वजन रखने की क्षमता होनी चाहिए जैसे 500 kilogram प्रति shelf या कुछ और।"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "एक seller पर कितना"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "एक ही साल का कितना कितना weight है?"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "ये आप seller से discuss कर सकते हैं।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "आप बस ये बता दीजिए कि आपको कितनी load capacity चाहिए जैसे 500 kg या कुछ और।"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 23,
      "speaker": "caller",
      "text": "Hundred gram hundred gram କେତେ?"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "जी मैं समझ गया।"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "आपकी lot capacity note कर ली है।"
    },
    {
      "i": 26,
      "speaker": "bot",
      "text": "अब बताइए कि आपको rack की height कितनी चाहिए जैसे 6 feet या 7 feet या कुछ और।"
    },
    {
      "i": 27,
      "speaker": "caller",
      "text": "आपके"
    },
    {
      "i": 28,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 29,
      "speaker": "bot",
      "text": "आपकी lot capacity 100 kilogram note कर ली है।"
    }
  ]
}
